import { defineConfig } from 'vite'
import react from '@vitejs/plugin-react'
import tailwindcss from '@tailwindcss/vite'

// https://vite.dev/config/
export default defineConfig({
  plugins: [
    react(),
    tailwindcss(),
  ],
})

import React, { useState } from 'react';
import { IntroSplash } from './components/IntroSplash';
import { Navbar } from './components/Navbar';
import { Hero } from './components/Hero';
import { Framework } from './components/Framework';
import { Services } from './components/Services';
import { FounderSpotlight } from './components/FounderSpotlight';
import { AuditForm } from './components/AuditForm';
import { Footer } from './components/Footer';

export const App: React.FC = () => {
  const [showIntro, setShowIntro] = useState(true);

  return (
    <>
      {showIntro && <IntroSplash onEnter={() => setShowIntro(false)} />}
      <div className={`min-h-screen flex flex-col bg-[#05070E] text-slate-100 transition-opacity duration-700 ${showIntro ? 'opacity-0 h-0 overflow-hidden' : 'opacity-100'}`}>
        <Navbar />
        <main className="flex-grow">
          <Hero />
          <Framework />
          <Services />
          <FounderSpotlight />
          <AuditForm />
        </main>
        <Footer />
      </div>
    </>
  );
};

@import "tailwindcss";

@theme {
  --color-brand-cobalt: #001489;
  --color-brand-vibrant: #0A25C9;
  --color-brand-orange: #F25A24;
  --color-brand-orange-hover: #d94917;
  --color-brand-slate: #8C827A;
  --color-brand-navy: #080D1A;
  --color-brand-card-navy: #0F172A;
  --color-brand-light-bg: #F8FAFC;

  --font-serif: "DM Serif Display", serif;
  --font-sans: "Inter", sans-serif;
  --font-display: "Montserrat", sans-serif;
}

body {
  font-family: var(--font-sans);
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import { App } from './App';
import './index.css';

ReactDOM.createRoot(document.getElementById('root')!).render(
  <React.StrictMode>
    <App />
  </React.StrictMode>,
);

import React from 'react';
import { Logo } from './Logo';

export const Footer: React.FC = () => {
  return (
    <footer className="bg-slate-950 text-slate-400 py-12 border-t border-slate-800 text-sm">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 flex flex-col sm:flex-row items-center justify-between gap-6">
        <Logo variant="dark" />
        <div className="text-xs text-slate-500 text-center sm:text-right">
          &copy; {new Date().getFullYear()} Auburn Professional Branding (APB). All rights reserved. • Auburn, Alabama
        </div>
      </div>
    </footer>
  );
};

import React from 'react';
import { Search, Award, MessageSquare, Zap, CheckSquare, RefreshCw } from 'lucide-react';

const stages = [
  {
    num: '01',
    title: 'Discovery',
    desc: 'Local search visibility and Google Map Pack positioning so buyers locate you first.',
    icon: Search,
  },
  {
    num: '02',
    title: 'Trust',
    desc: 'Elite brand consistency, verified credentials, and high-velocity social proof.',
    icon: Award,
  },
  {
    num: '03',
    title: 'Contact',
    desc: '1-click mobile calling, instant estimate triggers, and frictionless intake forms.',
    icon: MessageSquare,
  },
  {
    num: '04',
    title: 'Response',
    desc: 'Nova AI automated 15-second text-back to capture leads before they call competitors.',
    icon: Zap,
    highlight: true,
  },
  {
    num: '05',
    title: 'Conversion',
    desc: 'Transparent pricing presentation, automated follow-ups, and streamlined closing.',
    icon: CheckSquare,
  },
  {
    num: '06',
    title: 'Retention',
    desc: 'Systematized review generation, recurring maintenance agreements, and cross-sells.',
    icon: RefreshCw,
  },
];

export const Framework: React.FC = () => {
  return (
    <section id="framework" className="py-20 bg-white border-y border-slate-200">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center max-w-3xl mx-auto mb-16">
          <span className="text-[#F25A24] font-display font-bold text-xs uppercase tracking-widest">
            Revenue Engineering
          </span>
          <h2 className="font-serif text-3xl sm:text-4xl font-bold text-slate-900 mt-2 mb-4">
            The APB 6-Stage Revenue Model
          </h2>
          <p className="text-slate-600 text-base">
            We don't merely design logos. We systematically audit and optimize every touchpoint where potential clients either convert or leak money.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
          {stages.map((stg) => {
            const IconComponent = stg.icon;
            return (
              <div
                key={stg.num}
                className={`p-6 rounded-2xl border transition duration-300 ${
                  stg.highlight
                    ? 'bg-orange-50/40 border-[#F25A24] shadow-md'
                    : 'bg-slate-50 border-slate-200 hover:border-[#001489] hover:shadow-sm'
                }`}
              >
                <div className="flex items-center justify-between mb-4">
                  <span className="text-sm font-bold text-[#8C827A] font-mono">
                    {stg.num}
                  </span>
                  <div
                    className={`w-10 h-10 rounded-xl flex items-center justify-center ${
                      stg.highlight
                        ? 'bg-[#F25A24] text-white'
                        : 'bg-blue-100 text-[#001489]'
                    }`}
                  >
                    <IconComponent className="w-5 h-5" />
                  </div>
                </div>

                <h3 className="text-lg font-bold text-slate-900 mb-2 font-serif">
                  {stg.title}
                </h3>
                <p className="text-sm text-slate-600 leading-relaxed">
                  {stg.desc}
                </p>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};

import React from 'react';

interface LogoProps {
  variant?: 'light' | 'dark';
  className?: string;
}

export const Logo: React.FC<LogoProps> = ({ variant = 'light', className = '' }) => {
  const isDark = variant === 'dark';
  return (
    <div className={`flex items-center gap-3 ${className}`}>
      <svg className="w-10 h-10 transform transition duration-300 hover:scale-105" viewBox="0 0 100 100" fill="none">
        <circle cx="50" cy="50" r="44" stroke="#F25A24" stroke-width="7" stroke-dasharray="190 80" stroke-linecap="round" />
        <path d="M42 35 C46 32 54 30 62 31 C68 32 75 37 76 43 C72 41 68 42 66 45 C73 45 76 49 75 55 C70 53 66 54 64 58 C68 62 67 69 62 73 C58 66 57 60 52 56 C46 64 42 70 36 75 C41 68 43 60 41 53 C36 58 31 63 26 67 C30 58 34 50 37 42 C33 46 29 50 25 54 C28 44 34 37 42 35 Z" fill={isDark ? "#0A25C9" : "#001489"} />
        <polygon points="46,41 52,42 49,44" fill="#FFFFFF" />
      </svg>
      <div className="flex flex-col">
        <span className={`font-serif text-2xl font-bold tracking-tight leading-none ${isDark ? 'text-white' : 'text-[#001489]'}`}>
          Auburn
        </span>
        <span className="font-display text-[9px] font-bold tracking-[0.2em] text-[#8C827A] uppercase leading-none mt-1">
          Professional Branding
        </span>
      </div>
    </div>
  );
};

import React from 'react';
import { Palette, Bot, Globe, MapPin, Database, Send } from 'lucide-react';

const services = [
  {
    title: 'Brand Architecture & Identity',
    desc: 'Complete identity systems, vector emblems, corporate color theory, and digital asset kits that position you as the premium authority in your market.',
    icon: Palette,
    bullets: ['Primary & Secondary Logo Suites', 'Full Brand Guidelines Document', 'Asset Kits for Print & Web'],
  },
  {
    title: 'Nova Speed-to-Lead Automation',
    desc: 'Never forfeit high-ticket jobs to missed calls. Nova intercepts missed inquiries with an automated, customized text within 15 seconds.',
    icon: Bot,
    bullets: ['Missed-Call AI Text-Back', '24/7 Inquiry Qualification', 'Direct Calendar Self-Booking'],
  },
  {
    title: 'High-Converting Web Systems',
    desc: 'Ultra-fast, mobile-first React and Tailwind architectures built to transform inbound search traffic into qualified phone calls and appointments.',
    icon: Globe,
    bullets: ['Performance Vitals 95+', 'Integrated Direct Booking', 'SEO Structured Schema'],
  },
  {
    title: 'Local Market Dominance',
    desc: 'Google Business Profile optimization, local service area pages, and citation authority that capture top placement in regional Map Packs.',
    icon: MapPin,
    bullets: ['Google Map Pack Ranking', 'Localized Service Hubs', 'Review Acceleration Engine'],
  },
  {
    title: 'CRM & Pipeline Engineering',
    desc: 'Structured database systems in Airtable with automated status notifications, estimate tracking, and multi-stage deal pipelines.',
    icon: Database,
    bullets: ['Automated Stage Triggers', 'GA4 Goal Event Tracking', 'Multi-Channel Alert Dispatch'],
  },
  {
    title: 'Direct Outreach Systems',
    desc: 'Outbound B2B infrastructure connecting trade contractors with commercial accounts, property managers, and general builders.',
    icon: Send,
    bullets: ['Commercial Prospect Lists', 'Automated Email Sequences', 'Inbox Deliverability Guard'],
  },
];

export const Services: React.FC = () => {
  return (
    <section id="services" className="py-24 bg-[#F8FAFC]">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="text-center max-w-3xl mx-auto mb-16">
          <span className="text-[#F25A24] font-display font-bold text-xs uppercase tracking-widest">
            Capabilities
          </span>
          <h2 className="font-serif text-3xl sm:text-4xl font-bold text-slate-900 mt-2 mb-4">
            Unified Brand &amp; Automation Architecture
          </h2>
          <p className="text-slate-600 text-base">
            We merge design prestige with operational systems so your business commands higher rates and captures every customer inquiry.
          </p>
        </div>

        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-8">
          {services.map((svc, i) => {
            const Icon = svc.icon;
            return (
              <div
                key={i}
                className="bg-white p-8 rounded-2xl shadow-sm border border-slate-200 hover:shadow-md hover:border-[#001489] transition duration-300 flex flex-col justify-between"
              >
                <div>
                  <div className="w-12 h-12 bg-blue-50 text-[#001489] rounded-xl flex items-center justify-center mb-6">
                    <Icon className="w-6 h-6" />
                  </div>
                  <h3 className="text-xl font-bold text-slate-900 mb-3 font-serif">
                    {svc.title}
                  </h3>
                  <p className="text-slate-600 text-sm leading-relaxed mb-6">
                    {svc.desc}
                  </p>
                </div>

                <ul className="text-xs text-slate-500 space-y-2 border-t border-slate-100 pt-4">
                  {svc.bullets.map((b, idx) => (
                    <li key={idx} className="flex items-center gap-2">
                      <span className="w-1.5 h-1.5 rounded-full bg-[#F25A24]" />
                      <span>{b}</span>
                    </li>
                  ))}
                </ul>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
};
